const WT_ID={WATER:0,WET:1,SAND:2,GRASS:3,DARK:4,ROCK:5,ARENA:6,TREE:7,BOULDER:8,FLOOR:10,WALL:11,CARPET:12,REED:13,DRIFT:14,
  FLOWER:15,STUMP:16,VENT:17,PILLAR:18,RUIN:19,RUG:20,PLANTER:21,BENCH:22,CRATE:23,FIRE:80,STATUE:81,LAVA:82};
const WT_ZSET=['shore','greenmarch','ashen','godlands','frostreach','bonewaste'];
// Higher priority terrain draws its edge pieces onto lower neighbours. path>meadow so thin Haven paths stay continuous.
const WT_PRIO={water:0,pond:0,wet:1,sand:2,grass:3,meadow:3,path:3.5,frost:3.6,ash:4,bone:4.5,rock:5,arena:6,floor:7,lava:-1};
// terrain -> [tile set, ground key, edge key]
const WT_TER={water:['shore','water',null],wet:['shore','wet','wet'],sand:['shore','sand','sand'],grass:['greenmarch','grass','grass'],
  frost:['frostreach','snow','snow'],ice:['frostreach','ice',null],ash:['ashen','ash','ash'],bone:['bonewaste','bone','bone'],rock:['godlands','rock','rock'],arena:['godlands','arena','arena'],lava:['ashen','lava',null],
  pond:['haven','pond',null],path:['haven','path','path'],meadow:['haven','meadow','meadow'],floor:['haven','floor','floorCurb'],
  carpet:['haven','carpet',null],vfloor:['haven','vaultFloor',null]};
const WT_DECO={7:'tree',8:'boulder',13:'reed',14:'drift',15:'flower',16:'stump',17:'vent',18:'pillar',19:'ruin',80:'campfire',81:'statue',21:'planter',22:'bench',23:'crate'};
function wtSet(name){return name==='haven'?HAVEN_TILES:WORLD_TILES[name];}
function wtHash(x,y,s){let n=Math.imul(x|0,374761393)+Math.imul(y|0,668265263)+Math.imul(s|0,1442695041)|0;n=Math.imul(n^(n>>>13),1274126177);return ((n^(n>>>16))>>>0)/4294967296;}
function wtPick(list,x,y){
  if(list.length===1)return list[0];
  const r=wtHash(x,y,1);if(r<0.55)return list[0];
  return list[1+(Math.floor((r-0.55)/0.45*(list.length-1))%(list.length-1))];
}
// Classify a map cell: returns {k:'wall',set} | {k:'ground',ter} | {k:'void'}, plus deco sprite name.
// wd needs tiles, zone, w, h, isHub, isVault (as in game.js).
function wtClassify(wd,x,y){
  const out=(x<0||y<0||x>=wd.w||y>=wd.h);
  if(out){
    if(wd.isVault)return {k:'void'};
    return {k:'ground',ter:wd.isHub?'meadow':'water'};   // Haven: meadows run off every edge
  }
  const T=wd.tiles[y*wd.w+x],Z=wd.zone[y*wd.w+x],I=WT_ID,deco=WT_DECO[T]||null;
  if(T===I.WALL)return {k:'wall',set:(wd.isHub||wd.isVault)?'haven':(WT_ZSET[Z]||'godlands')};
  if(wd.isHub){
    let b='meadow';
    if(T===I.FLOOR||T===I.PLANTER||T===I.BENCH||T===I.CRATE||T===I.PILLAR)b='floor';
    else if(T===I.CARPET)b='carpet';else if(T===I.WATER)b='pond';else if(T===I.SAND)b='path';
    return {k:'ground',ter:b,deco};
  }
  if(wd.isVault)return {k:'ground',ter:T===I.CARPET?'carpet':'vfloor',deco};
  const zg=Z===0?'sand':Z===1?'grass':Z===2?'ash':Z===3?'rock':Z===4?'frost':Z===5?'bone':'water';
  const B={0:'water',1:'wet',2:'sand',3:'grass',4:'ash',5:'rock',6:'arena',82:'lava',101:'frost',102:'bone',103:'ice',13:'wet',14:'sand',17:'ash',18:'rock',
    19:Z===4?'frost':Z===5?'bone':Z===2?'ash':'rock',81:'rock',23:'sand',7:Z===4?'frost':Z===5?'bone':Z>=2?'ash':'grass',15:Z===4?'frost':'grass',16:Z===4?'frost':Z===5?'bone':Z>=2?'ash':'grass',8:zg,80:zg};
  return {k:'ground',ter:(T in B)?B[T]:zg,deco};
}
// Returns {layers:[[setName,rows],...], deco:[setName,spriteName]|null}. Paint layers in order ('.' = skip).
function wtLayers(wd,x,y){
  const c=wtClassify(wd,x,y),L=[];
  if(c.k==='void')return {layers:L,deco:null};
  const cl=(X,Y)=>wtClassify(wd,X,Y),isW=(X,Y)=>cl(X,Y).k==='wall';
  if(c.k==='wall'){
    const v=c.set,wl=wtSet(v).wall;
    const N=isW(x,y-1),S=isW(x,y+1),Wd=isW(x-1,y),E=isW(x+1,y);
    if(wd.isHub){
      const k=wd.wallKind?wd.wallKind[y*wd.w+x]:0;
      const straight=(N&&S&&!E&&!Wd)||(E&&Wd&&!N&&!S);
      const post=k===2||(k===1&&!straight);          // posts only at corners and ends
      if(post)L.push([v,wl[S?'postTop':'postFace']]);
      else L.push([v,wl[(S?'hedgeTop':'hedgeFace')+(wtHash(x,y,3)<0.35?'2':'')]]);
      return {layers:L,deco:null};
    }
    const top=wd.isVault?'vaultTop':'wallTop',face=wd.isVault?'vaultFace':'wallFace';
    if(!S&&!(wd.isVault&&cl(x,y+1).k==='void')){
      L.push([v,wl[face]]);
      if(!N)L.push([v,wl.edgeN]);if(!Wd)L.push([v,wl.faceEdgeL]);if(!E)L.push([v,wl.faceEdgeR]);
      return {layers:L,deco:null};
    }
    let all=true;for(let dy=-1;dy<=1&&all;dy++)for(let dx=-1;dx<=1;dx++)if(!isW(x+dx,y+dy)){all=false;break;}
    if(all)return {layers:[[v,wl.wallDeep||wl[top]]],deco:null};
    L.push([v,wl[top]]);
    if(!N)L.push([v,wl.edgeN]);if(!Wd)L.push([v,wl.edgeL]);if(!E)L.push([v,wl.edgeR]);
    if(N&&Wd&&!isW(x-1,y-1))L.push([v,wl.cornerNW]);
    if(N&&E&&!isW(x+1,y-1))L.push([v,wl.cornerNE]);
    if(Wd&&!isW(x-1,y+1))L.push([v,wl.cornerSW]);
    if(E&&!isW(x+1,y+1))L.push([v,wl.cornerSE]);
    return {layers:L,deco:null};
  }
  const ter=c.ter,[st,gk]=WT_TER[ter],G=wtSet(st).ground[gk];
  if(ter==='floor'){const q=G[Math.floor(wtHash(x>>1,y>>1,4)*G.length)];L.push([st,q[(x&1)+2*(y&1)]]);}
  else L.push([st,wtPick(G,x,y)]);
  const terOf=(X,Y)=>{const o=cl(X,Y);return o.k==='ground'?o.ter:null;};
  const D4=[['n',0,-1],['s',0,1],['w',-1,0],['e',1,0]];
  let over=false;
  if(ter==='carpet'){const tr=HAVEN_TILES.edges.carpetTrim;for(const [d,dx,dy] of D4)if(terOf(x+dx,y+dy)!=='carpet')L.push(['haven',tr[d]]);}
  else if(ter==='lava'){const rm=WORLD_TILES.ashen.lavaRims;for(const [d,dx,dy] of D4)if(terOf(x+dx,y+dy)!=='lava')L.push(['ashen',rm[d]]);}
  else{
    const p0=(ter in WT_PRIO)?WT_PRIO[ter]:-9,nb={};
    for(const [d,dx,dy] of [['n',0,-1],['s',0,1],['w',-1,0],['e',1,0],['nw',-1,-1],['ne',1,-1],['sw',-1,1],['se',1,1]])nb[d]=terOf(x+dx,y+dy);
    const hs=[...new Set(Object.values(nb).filter(b=>b&&((b in WT_PRIO)?WT_PRIO[b]:-9)>p0&&WT_TER[b][2]))].sort((a,b)=>WT_PRIO[a]-WT_PRIO[b]);
    const alt=wtHash(x,y,6)<0.5?'2':'';
    for(const b of hs){
      const [bs,,ek]=WT_TER[b],es=wtSet(bs).edges[ek];
      for(const d of ['n','s','w','e'])if(nb[d]===b){L.push([bs,es[d+alt]]);over=true;}
      for(const [d,a1,a2] of [['nw','n','w'],['ne','n','e'],['sw','s','w'],['se','s','e']])
        if(nb[d]===b&&nb[a1]!==b&&nb[a2]!==b){L.push([bs,es[d]]);over=true;}
    }
    if(ter==='ice'){
      const rm=wtSet('frostreach').iceRims;
      if(rm)for(const [d,dx,dy] of D4)if(terOf(x+dx,y+dy)!=='ice')L.push(['frostreach',rm[d]]);
    }
    const near=(name,rad)=>{
      for(let dy=-rad;dy<=rad;dy++)for(let dx=-rad;dx<=rad;dx++){
        if(!dx&&!dy)continue;
        if(terOf(x+dx,y+dy)===name)return true;
      }
      return false;
    };
    if(ter==='grass'&&near('frost',2))L[0]=['frostreach',wtPick(wtSet('frostreach').blend.frostGrass,x,y)];
    else if(ter==='ash'&&near('frost',2))L[0]=['frostreach',wtPick(wtSet('frostreach').blend.slush,x,y)];
    else if(ter==='ash'&&near('bone',2))L[0]=['bonewaste',wtPick(wtSet('bonewaste').blend.ashDust,x,y)];
    else if(ter==='rock'&&near('bone',2))L[0]=['bonewaste',wtPick(wtSet('bonewaste').blend.rockDust,x,y)];
  }
  if(!over&&!c.deco&&!['carpet','lava','floor','vfloor','wet','arena','path','pond'].includes(ter)&&wtHash(x,y,5)<(ter==='meadow'?0.03:0.05)){
    const dets=wtSet(st)[ter==='water'?'waterDetails':'details']||{},dl=Object.values(dets);
    if(dl.length)L.push([st,dl[Math.floor(wtHash(x,y,9)*dl.length)]]);
  }
  const shade=(X,Y,dir)=>{
    const ws=cl(X,Y).set;
    if(ws==='haven')L.push(['haven',HAVEN_TILES.edges[(['meadow','path','pond'].includes(ter)?'meadowShadow':ter==='vfloor'?'vaultShadow':'shadow')+dir]]);
    else L.push([ws,wtSet(ws).wall['shadow'+dir]]);
  };
  if(isW(x,y-1))shade(x,y-1,'N');
  if(isW(x-1,y))shade(x-1,y,'W');
  let deco=null;
  if(c.deco){
    let ds;
    if(wd.isHub||wd.isVault)ds='haven';
    else{
      const Z=wd.zone[y*wd.w+x];
      ds={tree:'greenmarch',flower:'greenmarch',campfire:'greenmarch',reed:'shore',drift:'shore',crate:'shore',vent:'ashen',pillar:'godlands',statue:'godlands'}[c.deco]||WT_ZSET[Z]||'godlands';
      if(c.deco==='stump')ds=Z===4?'frostreach':Z===5?'bonewaste':Z>=2?'ashen':'greenmarch';
    }
    if(!wtSet(ds).props[c.deco])ds=['greenmarch','godlands','shore','ashen','haven'].find(s=>wtSet(s).props[c.deco]);
    deco=[ds,c.deco];
  }
  return {layers:L,deco};
}
// Haven only: decoration for cells OUTSIDE the 96x96 map (the meadow that runs off every edge). ~5% get a tree.
function wtOutsideDeco(x,y){return wtHash(x,y,21)<0.05?['haven','tree']:null;}
const _wtRGB={};
function wtRGB(set,ch){const k=set+ch;let c=_wtRGB[k];if(!c){const n=parseInt(wtSet(set).pal[ch].slice(1),16);c=_wtRGB[k]=[(n>>16)&255,(n>>8)&255,n&255];}return c;}
// Per-pixel colour for tileRGB-style rasterizers.
function wtPixel(layers,px,py){for(let i=layers.length-1;i>=0;i--){const ch=layers[i][1][py][px];if(ch!=='.')return wtRGB(layers[i][0],ch);}return [8,12,16];}
if(typeof module!=='undefined')module.exports={WORLD_TILES,HAVEN_TILES,wtLayers,wtPixel,wtClassify,wtHash,wtRGB,wtOutsideDeco};
